import json, pathlib, html, re
P=pathlib.Path(__file__).resolve().parent
Q=[]
def add(t, section, level, evidence, question, options, answer, explanation, source, hint='Сопоставьте утверждение с адресами, кодировкой или поведением устройства.'):
    n=len(Q)+1
    q=dict(id=f'PQL-{n:03d}',type=t,section=section,level=level,evidence=evidence,question=question,options=options,correct=answer,explanation=explanation,source=source,hint=hint)
    Q.append(q)
def single(section,level,ev,q,opts,a,why,src):add('single',section,level,ev,q,opts,a,why,src)
def multiple(section,level,ev,q,opts,a,why,src):add('multiple',section,level,ev,q,opts,a,why,src)
def match(section,level,ev,q,left,right,keys,why,src):add('match',section,level,ev,q,{'left':left,'right':right},keys,why,src)
def order(section,level,ev,q,items,keys,why,src):add('order',section,level,ev,q,items,keys,why,src)
